class VamtamThemePostFeaturedImage extends elementorModules.frontend.handlers.Base{onInit(...e){super.onInit(...e),this.handleShowProuductGallery()}handleShowProuductGallery(){if(!this.$element.hasClass("vamtam-has-post-gallery"))return;const e=this.$element.find(".vamtam-product-gallery.swiper");e.length&&e.each(function(){const e=jQuery(this);new window.elementorFrontend.utils.swiper(e,{loop:!0,allowTouchMove:!1,navigation:{nextEl:".swiper-button-next",prevEl:".swiper-button-prev"},on:{init:function(){const e=this;e.$el.on("mouseleave",()=>{setTimeout(()=>{e.slideTo(1,0)},400)})}}})})}}jQuery(window).on("elementor/frontend/init",()=>{if(elementorFrontend.elementsHandler&&elementorFrontend.elementsHandler.attachHandler)elementorFrontend.elementsHandler.attachHandler("theme-post-featured-image",VamtamThemePostFeaturedImage);else{const e=e=>{elementorFrontend.elementsHandler.addHandler(VamtamThemePostFeaturedImage,{$element:e})};elementorFrontend.hooks.addAction("frontend/element_ready/theme-post-featured-image.default",e,100)}});